"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["17938"],{51015(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>c,frontMatter:()=>s,contentTitle:()=>r,toc:()=>l,assets:()=>h});var a=JSON.parse('{"id":"qiangguo/cometoadmitmistake","title":"","description":"[Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n] posted on 2006-08-07 1024","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/cometoadmitmistake.md","sourceDirName":"qiangguo","slug":"/qiangguo/cometoadmitmistake","permalink":"/en/qiangguo/cometoadmitmistake","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"cometoadmitmistake","title":"","hide_table_of_contents":true,"sidebar_label":"Netizen \\"Math,\\" if you truly have any academic spirit, stand up and admit your mistakes!"},"sidebar":"qiangguoSidebar","previous":{"title":"\u96BE\u9053\u7F51\u7EDC\u5DE6\u6D3E\u90FD\u7531\u4E00\u7FA4\u4E0D\u5B66\u65E0\u672F\u8005\u7EC4\u6210\uFF1F","permalink":"/en/qiangguo/thenetworkleft"},"next":{"title":"If America invades North Korea again \u2014 the preconditions for China not entering the war (please let this through)","permalink":"/en/qiangguo/ahypothesis"}}'),i=n(74848),o=n(28453);let s={id:"cometoadmitmistake",title:"",hide_table_of_contents:!0,sidebar_label:'Netizen "Math," if you truly have any academic spirit, stand up and admit your mistakes!'},r='Netizen "Math," If You Have Any Academic Integrity, Step Up and Admit Your Error!',h={},l=[];function m(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"netizen-math-if-you-have-any-academic-integrity-step-up-and-admit-your-error",children:'Netizen "Math," If You Have Any Academic Integrity, Step Up and Admit Your Error!'})}),"\n",(0,i.jsxs)(t.blockquote,{children:["\n",(0,i.jsx)(t.p,{children:"[Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n] posted on 2006-08-07 10:40:24"}),"\n"]}),"\n",(0,i.jsxs)(t.blockquote,{children:["\n",(0,i.jsx)(t.p,{children:"Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n"}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:'This is a perfectly normal academic question. Netizen "Math" proposed that all human thought can be represented in binary digits. This ID used a very simple method to prove it wrong. Netizen "Math," if you have any academic integrity, step up and admit your error!'}),"\n",(0,i.jsx)(t.p,{children:'Peking University and Tsinghua have been competing for a long time, but when it comes to mathematics, Tsinghua has no contest with Peking University. I hear Netizen "Math" is from Tsinghua, though not a mathematics major, so having some academic errors is not surprising. But anyone from Tsinghua, no matter how brilliant they think they are, should still admit mistakes when they make them. At the very least, anyone from Peking University would never try to cover up an error!'}),"\n",(0,i.jsx)(t.p,{children:'As for the clamoring of others, those people don\'t even have the most basic mathematical knowledge. This ID has no time to wrangle with them. Some things are too kindergarten-level, and this ID has no obligation to teach them. Even if they remain forever unenlightened, that\'s their problem \u2014 this ID will just enjoy the show. But if Netizen "Math" still has a shred of academic conscience, please step up and admit the error, or academically demonstrate that this ID is wrong. If this ID is truly wrong, this ID will certainly admit the mistake. But on this particular question, that\'s impossible. Because if this ID were wrong, then the method used to prove this ID wrong would necessarily also prove that set theory and some of the most foundational mathematics contain errors. In that case, Netizen "Math" would become a great master \u2014 but the chance of that happening is probably zero, even if you wait until the end of the universe!'}),"\n",(0,i.jsx)(t.p,{children:"The proof is appended below once more:"}),"\n",(0,i.jsx)(t.p,{children:'As for that Math ID who routinely makes logical blunders, he recently claimed as if he\'d discovered a new continent: "From the standpoint of mathematical theory, dichotomy, that is, the use of binary numbers, can express all human thought and laws of motion, because these thoughts can all be stored in binary computers." I have no idea what kind of "mathematical theory" this so-called math ID is referring to. Does merely calling yourself a Math ID entitle you to spout mathematical nonsense? Very well then, let us very mathematically examine this so-called discovery or claim by the Math ID:'}),"\n",(0,i.jsx)(t.p,{children:'Let us assume his claim holds \u2014 that all human thought and laws of motion can be represented in binary numbers. Then let us line up all these binary numbers representing all human thought and laws of motion. Now consider this binary number: its Nth digit differs from the Nth digit of the Nth binary number in the lineup above (for example, if the latter is 1, the former is 0, and vice versa). Clearly, this binary number is not among those representing all human thought and laws of motion, yet this binary number represents the following thought: "its Nth digit differs from the Nth digit of the Nth binary number in the lineup." In other words, this thought is not contained in the totality of human thought and laws of motion \u2014 which is a contradiction. By the simplest proof by contradiction, the assumption "all human thought and laws of motion can be represented in binary numbers" does not hold. All human thought and laws of motion cannot all be represented in binary numbers.'}),"\n",(0,i.jsx)(t.p,{children:"The proof method above is actually not this ID's invention. It is a classic mathematical proof technique with a common name: the \"diagonal method.\" It first appeared in Cantor's series of proofs regarding set theory in the 19th century. Not to mention the 20th century's mathematical development that surpassed the sum of all previous centuries \u2014 anyone with a basic understanding of this 19th-century mathematical knowledge could not possibly assert such an absurd proposition."})]})}function c(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(m,{...e})}):m(e)}},28453(e,t,n){n.d(t,{R:()=>s,x:()=>r});var a=n(96540);let i={},o=a.createContext(i);function s(e){let t=a.useContext(o);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),a.createElement(o.Provider,{value:t},e.children)}}}]);